static void need(bool x,const char*s){if(!x)throw std::runtime_error(s);}
static bp::v9::Payload dummy(uint64_t,bool,const std::array<unsigned,21>&,unsigned){return {};}
static auto geometry(){bp::RoundState s;std::vector<Geometry>g;auto w=s.history_words();for(unsigned i=0;i<21;++i)g.push_back({s.fold_length(i),w[i].width});return g;}
static void drain(Controller&c){for(unsigned i=0;i<400;++i){if(c.drained())return;c.advance(dummy);}throw std::runtime_error("guard controller drain timeout");}
static FiniteProtection&protect(Controller&c){auto*p=dynamic_cast<FiniteProtection*>(c.port.source.guard());need(p,"protection missing");return *p;}
static Controller controller(Protect p,Mode m=Mode::Recurrent){Controller c(m,geometry());c.port.source.attach_guard(std::make_unique<FiniteProtection>(c.port.source.selected_widths(),p,m==Mode::Direct));return c;}
